import { z } from "zod";
import { ModelGenerationSettingsSchema, TargetInterpretationSourceReferenceSchema, } from "./schemas.js";
import { DefensibilitySchema, FreshnessRiskSchema, MaterialitySchema, ProofQualitySchema, SupportStatusSchema, } from "./fit-assessment-schemas.js";
const Sha256Schema = z.string().regex(/^[a-f0-9]{64}$/);
const RelativePathSchema = z.string().min(1).refine((value) => !value.startsWith("/") && !/^[A-Za-z]:[\\/]/.test(value), "Path must be relative to the workspace");
export const RoleResumePlanningModeSchema = z.literal("market-positioning");
export const RoleResumePlanTrustStateSchema = z.enum([
    "deterministic-approved",
    "human-approved",
    "human-edited",
    "proposed",
]);
export const RoleResumeSectionTypeSchema = z.enum([
    "headline",
    "professional-summary",
    "core-capabilities",
    "selected-impact",
    "professional-experience",
    "selected-projects",
    "technical-capabilities",
    "leadership-capabilities",
    "education",
    "certifications",
    "additional-information",
]);
export const ResumeContentTypeSchema = z.enum([
    "role-title",
    "capability-theme",
    "scope",
    "responsibility",
    "achievement",
    "quantified-outcome",
    "technology",
    "domain",
    "leadership-behavior",
    "delivery-outcome",
    "product-outcome",
    "business-outcome",
    "education",
    "certification",
    "project",
]);
export const PlanDependencySchema = z.object({
    path: RelativePathSchema,
    sha256: Sha256Schema,
    manifestPath: RelativePathSchema,
    manifestSha256: Sha256Schema,
}).strict();
export const PlanElementProvenanceSchema = z.object({
    targetId: z.string().min(1),
    approvedInterpretationSha256: Sha256Schema,
    approvedMatchingSha256: Sha256Schema,
    approvedAssessmentSha256: Sha256Schema,
    evidenceSnapshotSha256: Sha256Schema,
    expectationIds: z.array(z.string().min(1)),
    assessmentIds: z.array(z.string().min(1)),
    approvedMatchIds: z.array(z.string().min(1)),
    evidenceIds: z.array(z.string().min(1)),
    sourceReferences: z.array(TargetInterpretationSourceReferenceSchema),
    planningPolicy: z.object({ name: z.string().min(1), version: z.string().min(1) }).strict(),
    deterministicInputs: z.record(z.union([z.string(), z.number(), z.boolean(), z.array(z.string())])),
    modelProposal: z.object({
        proposalId: z.string().min(1),
        provider: z.string().min(1),
        model: z.string().min(1),
        promptTemplateVersion: z.string().min(1),
    }).strict().optional(),
    reviewDecision: z.object({
        decision: z.enum(["accept", "edit"]),
        reviewer: z.object({ type: z.literal("human"), name: z.string().min(1).optional() }).strict(),
    }).strict().optional(),
}).strict();
export const PositioningThemeSchema = z.object({
    id: z.string().min(1),
    label: z.string().min(1),
    sourceExpectationIds: z.array(z.string().min(1)),
    sourceAssessmentIds: z.array(z.string().min(1)),
    approvedMatchIds: z.array(z.string().min(1)),
    evidenceIds: z.array(z.string().min(1)),
    rationale: z.string().min(1),
    emphasis: z.enum(["primary", "secondary", "supporting"]),
    provenance: PlanElementProvenanceSchema,
    trustState: RoleResumePlanTrustStateSchema,
}).strict();
export const PositioningCautionSchema = z.object({
    id: z.string().min(1),
    label: z.string().min(1),
    expectationIds: z.array(z.string().min(1)),
    evidenceIds: z.array(z.string().min(1)),
    rationale: z.string().min(1),
}).strict();
export const RolePositioningPlanSchema = z.object({
    targetRoleTitle: z.string().min(1),
    positioningScope: z.enum([
        "direct-role-positioning",
        "adjacent-role-positioning",
        "stretch-positioning",
        "insufficient-evidence",
    ]),
    primaryThemes: z.array(PositioningThemeSchema),
    secondaryThemes: z.array(PositioningThemeSchema),
    differentiationThemes: z.array(PositioningThemeSchema),
    cautionThemes: z.array(PositioningCautionSchema),
    narrativeOrder: z.array(z.string().min(1)),
    audience: z.object({
        primary: z.enum(["recruiter", "hiring-manager", "executive", "mixed"]),
        notes: z.array(z.string().min(1)),
    }).strict(),
    provenance: PlanElementProvenanceSchema,
    trustState: RoleResumePlanTrustStateSchema,
}).strict();
export const RoleResumeSectionPlanSchema = z.object({
    id: z.string().min(1),
    type: RoleResumeSectionTypeSchema,
    status: z.enum(["include", "optional", "exclude"]),
    objective: z.string().min(1),
    order: z.number().int().nonnegative(),
    sourceExpectationIds: z.array(z.string().min(1)),
    sourceAssessmentIds: z.array(z.string().min(1)),
    approvedMatchIds: z.array(z.string().min(1)),
    evidenceIds: z.array(z.string().min(1)),
    allowedContentTypes: z.array(ResumeContentTypeSchema),
    prohibitedContentTypes: z.array(ResumeContentTypeSchema),
    emphasisNotes: z.array(z.string().min(1)),
    cautionNotes: z.array(z.string().min(1)),
    maximumItemCount: z.number().int().positive().optional(),
    provenance: PlanElementProvenanceSchema,
    trustState: RoleResumePlanTrustStateSchema,
}).strict();
export const ResumeExpectationSelectionSchema = z.object({
    id: z.string().min(1),
    expectationId: z.string().min(1),
    assessmentId: z.string().min(1),
    decision: z.enum(["primary", "secondary", "supporting", "exclude", "defer"]),
    supportStatus: SupportStatusSchema,
    defensibility: DefensibilitySchema,
    materiality: MaterialitySchema,
    rationale: z.string().min(1),
    approvedMatchIds: z.array(z.string().min(1)),
    evidenceIds: z.array(z.string().min(1)),
    allowedSections: z.array(RoleResumeSectionTypeSchema),
    restrictions: z.array(z.string().min(1)),
    provenance: PlanElementProvenanceSchema,
    trustState: RoleResumePlanTrustStateSchema,
}).strict();
export const ResumeEvidenceSelectionSchema = z.object({
    id: z.string().min(1),
    evidenceId: z.string().min(1),
    decision: z.enum(["preferred", "allowed", "limited-use", "exclude"]),
    approvedMatchIds: z.array(z.string().min(1)),
    expectationIds: z.array(z.string().min(1)),
    permittedUses: z.array(ResumeContentTypeSchema),
    prohibitedUses: z.array(ResumeContentTypeSchema),
    proofQuality: ProofQualitySchema,
    freshnessRisk: FreshnessRiskSchema,
    limitations: z.array(z.string().min(1)),
    rationale: z.string().min(1),
    provenance: PlanElementProvenanceSchema,
    trustState: RoleResumePlanTrustStateSchema,
}).strict();
export const ResumeClaimBoundarySchema = z.object({
    id: z.string().min(1),
    expectationId: z.string().min(1).optional(),
    evidenceIds: z.array(z.string().min(1)),
    boundaryType: z.enum(["allowed", "allowed-with-caution", "prohibited", "requires-review"]),
    allowedClaimTypes: z.array(ResumeContentTypeSchema),
    prohibitedClaimTypes: z.array(ResumeContentTypeSchema),
    allowedScope: z.object({
        roleScope: z.array(z.string()).optional(),
        teamScope: z.array(z.string()).optional(),
        productScope: z.array(z.string()).optional(),
        technicalScope: z.array(z.string()).optional(),
        temporalScope: z.array(z.string()).optional(),
    }).strict().optional(),
    prohibitedInferences: z.array(z.string().min(1)),
    requiredQualifiers: z.array(z.string().min(1)),
    rationale: z.string().min(1),
    provenance: PlanElementProvenanceSchema,
    trustState: RoleResumePlanTrustStateSchema,
}).strict();
export const ResumeContentExclusionSchema = z.object({
    id: z.string().min(1),
    type: z.enum([
        "unsupported-expectation",
        "conflicting-expectation",
        "weak-evidence",
        "stale-evidence",
        "insufficient-specificity",
        "missing-metric",
        "privacy-restricted",
        "publication-restricted",
        "unapproved-source",
        "job-specific-only",
        "duplicate-theme",
        "not-relevant-to-role",
    ]),
    expectationIds: z.array(z.string().min(1)),
    evidenceIds: z.array(z.string().min(1)),
    rationale: z.string().min(1),
    severity: z.enum(["blocking", "high", "medium", "low"]),
    provenance: PlanElementProvenanceSchema,
    trustState: RoleResumePlanTrustStateSchema,
}).strict();
const ReferenceFields = {
    expectationIds: z.array(z.string().min(1)),
    approvedMatchIds: z.array(z.string().min(1)),
    evidenceIds: z.array(z.string().min(1)),
};
export const ResumePlanningRiskSchema = z.object({
    id: z.string().min(1),
    code: z.enum([
        "NO_PRIMARY_POSITIONING_THEME",
        "CRITICAL_EXPECTATION_EXCLUDED",
        "PRIMARY_THEME_PARTIALLY_SUPPORTED",
        "PRIMARY_THEME_USES_LIMITED_EVIDENCE",
        "HISTORICAL_EVIDENCE_OVERRELIANCE",
        "INSUFFICIENT_RECENT_EVIDENCE",
        "INSUFFICIENT_SPECIFICITY",
        "QUANTIFIED_OUTCOME_NOT_AVAILABLE",
        "CONTRADICTORY_EVIDENCE_PRESENT",
        "EVIDENCE_REUSED_EXCESSIVELY",
        "PLAN_INCOMPLETE",
        "ASSESSMENT_STALE",
        "MATCHING_STALE",
        "INTERPRETATION_STALE",
        "PROVENANCE_INCOMPLETE",
    ]),
    severity: z.enum(["critical", "high", "medium", "low"]),
    message: z.string().min(1),
    ...ReferenceFields,
}).strict();
export const ResumePlanningWarningSchema = z.object({
    id: z.string().min(1),
    code: z.enum([
        "NO_APPROVED_ROLE_ASSESSMENT",
        "ASSESSMENT_NOT_COMPLETE",
        "NO_STRONGLY_SUPPORTED_EXPECTATIONS",
        "NO_PRIMARY_EXPECTATIONS_SELECTED",
        "ONLY_HISTORICAL_EVIDENCE_AVAILABLE",
        "ONLY_SUPPORTING_EVIDENCE_AVAILABLE",
        "NO_QUANTIFIED_OUTCOMES_AVAILABLE",
        "ROLE_POSITIONING_REQUIRES_CAUTION",
        "MODEL_PLAN_REQUIRES_HUMAN_REVIEW",
        "PLAN_DOES_NOT_CONTAIN_RESUME_PROSE",
    ]),
    message: z.string().min(1),
    ...ReferenceFields,
}).strict();
export const ResumePlanningAmbiguitySchema = z.object({
    id: z.string().min(1),
    code: z.enum([
        "PRIMARY_VS_SECONDARY_THEME_UNCLEAR",
        "ROLE_SCOPE_UNCLEAR",
        "SENIORITY_BOUNDARY_UNCLEAR",
        "LEADERSHIP_SCOPE_UNCLEAR",
        "CURRENT_VS_HISTORICAL_CAPABILITY_UNCLEAR",
        "PROJECT_VS_EMPLOYMENT_EVIDENCE_BOUNDARY_UNCLEAR",
        "ACHIEVEMENT_VS_RESPONSIBILITY_UNCLEAR",
        "EVIDENCE_REUSE_BOUNDARY_UNCLEAR",
        "SECTION_INCLUSION_UNCLEAR",
    ]),
    message: z.string().min(1),
    ...ReferenceFields,
}).strict();
export const RoleResumePlanCompletenessSchema = z.object({
    status: z.enum(["empty", "partial", "complete"]),
    eligibleExpectationCount: z.number().int().nonnegative(),
    selectedExpectationCount: z.number().int().nonnegative(),
    excludedExpectationCount: z.number().int().nonnegative(),
    deferredExpectationCount: z.number().int().nonnegative(),
    plannedSectionCount: z.number().int().nonnegative(),
    primaryThemeCount: z.number().int().nonnegative(),
    claimBoundariesComplete: z.boolean(),
    provenanceComplete: z.boolean(),
    usableForResumeDrafting: z.boolean(),
    blockingReasons: z.array(z.string().min(1)),
}).strict();
export const RoleResumePlanProvenanceSchema = z.object({
    targetSha256: Sha256Schema,
    approvedInterpretationSha256: Sha256Schema,
    approvedInterpretationManifestSha256: Sha256Schema,
    approvedMatchingSha256: Sha256Schema,
    approvedMatchingManifestSha256: Sha256Schema,
    evidenceSnapshotSha256: Sha256Schema,
    approvedAssessmentSha256: Sha256Schema,
    approvedAssessmentManifestSha256: Sha256Schema,
    expectationSetSha256: Sha256Schema,
    assessmentSetSha256: Sha256Schema,
    approvedMatchSetSha256: Sha256Schema,
    evidenceSetSha256: Sha256Schema,
}).strict();
export const RoleResumeContentPlanSchema = z.object({
    schemaVersion: z.literal(1),
    id: z.string().min(1),
    targetId: z.string().min(1),
    targetType: z.literal("role"),
    mode: RoleResumePlanningModeSchema,
    roleTitle: z.string().min(1),
    approvedInterpretation: PlanDependencySchema,
    approvedMatching: PlanDependencySchema,
    approvedAssessment: PlanDependencySchema,
    planningPolicy: z.object({ name: z.string().min(1), version: z.string().min(1) }).strict(),
    positioning: RolePositioningPlanSchema,
    sections: z.array(RoleResumeSectionPlanSchema),
    expectationSelections: z.array(ResumeExpectationSelectionSchema),
    evidenceSelections: z.array(ResumeEvidenceSelectionSchema),
    claimBoundaries: z.array(ResumeClaimBoundarySchema),
    exclusions: z.array(ResumeContentExclusionSchema),
    risks: z.array(ResumePlanningRiskSchema),
    warnings: z.array(ResumePlanningWarningSchema),
    ambiguities: z.array(ResumePlanningAmbiguitySchema),
    completeness: RoleResumePlanCompletenessSchema,
    provenance: RoleResumePlanProvenanceSchema,
    createdAt: z.string().datetime(),
    updatedAt: z.string().datetime(),
}).strict();
export const RoleResumePlanManifestSchema = z.object({
    schemaVersion: z.literal(1),
    artifactType: z.enum(["deterministic", "approved"]),
    planId: z.string().min(1),
    targetId: z.string().min(1),
    mode: RoleResumePlanningModeSchema,
    planPath: RelativePathSchema,
    planSha256: Sha256Schema,
    policyName: z.string().min(1),
    policyVersion: z.string().min(1),
    targetSha256: Sha256Schema,
    approvedInterpretationSha256: Sha256Schema,
    approvedInterpretationManifestSha256: Sha256Schema,
    approvedMatchingSha256: Sha256Schema,
    approvedMatchingManifestSha256: Sha256Schema,
    evidenceSnapshotSha256: Sha256Schema,
    approvedAssessmentSha256: Sha256Schema,
    approvedAssessmentManifestSha256: Sha256Schema,
    expectationSetSha256: Sha256Schema,
    assessmentSetSha256: Sha256Schema,
    approvedMatchSetSha256: Sha256Schema,
    evidenceSetSha256: Sha256Schema,
    proposalId: z.string().min(1).optional(),
    proposalSha256: Sha256Schema.optional(),
    reviewSha256: Sha256Schema.optional(),
    createdAt: z.string().datetime(),
    updatedAt: z.string().datetime(),
}).strict();
export const ModelRoleResumePlanPayloadSchema = z.object({
    positioning: RolePositioningPlanSchema,
    sections: z.array(RoleResumeSectionPlanSchema),
    expectationSelections: z.array(ResumeExpectationSelectionSchema),
    evidenceSelections: z.array(ResumeEvidenceSelectionSchema),
    claimBoundaries: z.array(ResumeClaimBoundarySchema),
    exclusions: z.array(ResumeContentExclusionSchema),
    warnings: z.array(ResumePlanningWarningSchema),
    ambiguities: z.array(ResumePlanningAmbiguitySchema),
}).strict();
export const ResumePlanValidationIssueSchema = z.object({
    code: z.string().min(1),
    message: z.string().min(1),
    path: z.string().optional(),
}).strict();
export const RoleResumePlanProposalSchema = z.object({
    schemaVersion: z.literal(1),
    id: z.string().min(1),
    requestFingerprint: Sha256Schema,
    targetId: z.string().min(1),
    targetType: z.literal("role"),
    mode: RoleResumePlanningModeSchema,
    status: z.enum(["generated", "validation-failed", "ready-for-review", "reviewed"]),
    planningPolicy: z.object({ name: z.string().min(1), version: z.string().min(1) }).strict(),
    model: z.object({ provider: z.string().min(1), model: z.string().min(1), settings: ModelGenerationSettingsSchema }).strict(),
    prompt: z.object({
        templateId: z.string().min(1),
        templateVersion: z.string().min(1),
        policyVersion: z.string().min(1),
        renderedPromptSha256: Sha256Schema,
    }).strict(),
    input: z.object({
        targetSha256: Sha256Schema,
        approvedInterpretationSha256: Sha256Schema,
        approvedMatchingSha256: Sha256Schema,
        evidenceSnapshotSha256: Sha256Schema,
        approvedAssessmentSha256: Sha256Schema,
        deterministicPlanSha256: Sha256Schema,
        normalizedModelInputSha256: Sha256Schema,
    }).strict(),
    proposedPlan: ModelRoleResumePlanPayloadSchema.optional(),
    validationIssues: z.array(ResumePlanValidationIssueSchema),
    rawResponsePath: RelativePathSchema,
    rawResponseSha256: Sha256Schema,
    createdAt: z.string().datetime(),
    updatedAt: z.string().datetime(),
}).strict();
export const RoleResumePlanProposalManifestSchema = z.object({
    schemaVersion: z.literal(1),
    proposalId: z.string().min(1),
    requestFingerprint: Sha256Schema,
    targetId: z.string().min(1),
    proposalPath: RelativePathSchema,
    proposalSha256: Sha256Schema,
    rawResponsePath: RelativePathSchema,
    rawResponseSha256: Sha256Schema,
    provider: z.string().min(1),
    model: z.string().min(1),
    promptTemplateId: z.string().min(1),
    promptTemplateVersion: z.string().min(1),
    policyVersion: z.string().min(1),
    renderedPromptSha256: Sha256Schema,
    normalizedModelInputSha256: Sha256Schema,
    targetSha256: Sha256Schema,
    approvedInterpretationSha256: Sha256Schema,
    approvedMatchingSha256: Sha256Schema,
    evidenceSnapshotSha256: Sha256Schema,
    approvedAssessmentSha256: Sha256Schema,
    deterministicPlanSha256: Sha256Schema,
    createdAt: z.string().datetime(),
    updatedAt: z.string().datetime(),
}).strict();
export const RoleResumePlanReviewDecisionSchema = z.object({
    itemType: z.enum(["positioning", "section", "expectation", "evidence", "claim-boundary", "exclusion"]),
    itemId: z.string().min(1),
    decision: z.enum(["pending", "accept", "edit", "reject"]),
    editedValue: z.unknown().optional(),
    reviewNote: z.string().min(1).optional(),
    decidedAt: z.string().datetime().optional(),
}).strict();
export const RoleResumePlanReviewSchema = z.object({
    schemaVersion: z.literal(1),
    proposalId: z.string().min(1),
    targetId: z.string().min(1),
    status: z.enum(["in-progress", "completed"]),
    decisions: z.array(RoleResumePlanReviewDecisionSchema),
    reviewer: z.object({ type: z.literal("human"), name: z.string().min(1).optional() }).strict(),
    createdAt: z.string().datetime(),
    updatedAt: z.string().datetime(),
}).strict();
export const RoleResumePlanReviewManifestSchema = z.object({
    schemaVersion: z.literal(1),
    proposalId: z.string().min(1),
    targetId: z.string().min(1),
    reviewPath: RelativePathSchema,
    reviewSha256: Sha256Schema,
    proposalSha256: Sha256Schema,
    createdAt: z.string().datetime(),
    updatedAt: z.string().datetime(),
}).strict();
